sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    try {
        var empf_id = current.er_id;
        if (!empf_id)
            empf_id = current.ee_id;
        var case_task_query = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case_task');
        case_task_query.addQuery('aml_kyc_case', current.sys_id);
        case_task_query.query();
        var checkerID = "";
        if (case_task_query.next()) {
            checkerID = case_task_query.assigned_to.user_name;
        }

        var payload = {
            schemeCode: current.scheme_code + "",
            employerAccountCode: current.employer_account_code + "",
            memberAccountCode: current.member_account_code_1_ee + "",
            internalTrack: current.sensitive_flag_aml_type_1_er_risk + "",
            effectiveDate: current.sensitive_flag_aml_type_1_effective_date_er_risk + "",
            proposeAMLType: current.empf_aml_type_1_2_3_proposed_er_risk + "",
            transactionBlock: current.superhold_transaction_blocking_er_risk + "",
            transBlockEffectiveDate: current.super_trans_blocking_effective_date_er_risk + "",
            note: current.note_er_risk + "",
            noteEffectiveDate: current.note_effective_date_er_risk + "",
            maker: current.assigned_to.user_name + "",
            checker: checkerID + "",
            eMPFId: empf_id + "",
            fCRRResult: current.fcrr_result_er_risk + "",
            fCRREffectiveDate: current.fcrr_effective_date_er_risk + ""
        };
        var method = 'save-risk-info';
        var scheme = current.scheme_code.toLowerCase();

        //new MSSTrusteesCallUtils().createStagingRecord();
        new x_hsb11_mss_trus_0.MSSTrusteesCallUtils().createOutboundRecord(current.sys_id, payload, method, scheme);
    } catch (err) {
        gs.info("Trustees 60 - Got error while calling the script include" + err.message);
    }

})(current, previous);
